INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000750', 'Tekanan kapiler (Pc) adalah...', 'Capillary pressure (Pc) is...', 'option', 'PFC000000006', 'Inisialisasi', 'a:4:{i:0;s:68:"Perbedaan tekanan antara fasa non-wetting dan fasa wetting pada pori";i:1;s:23:"Tekanan total reservoir";i:2;s:25:"Tekanan overburden batuan";i:3;s:25:"Selisih tekanan dua sumur";}', 'a:4:{i:0;s:76:"The pressure difference between the non-wetting and wetting phases in a pore";i:1;s:28:"The total reservoir pressure";i:2;s:28:"The rock overburden pressure";i:3;s:41:"The pressure difference between two wells";}', '', 'Perbedaan tekanan antara fasa non-wetting dan fasa wetting pada pori', 'The pressure difference between the non-wetting and wetting phases in a pore', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000751', 'Persamaan tekanan kapiler untuk pori berbentuk tabung adalah...', 'The capillary pressure equation for a cylindrical pore is...', 'option', 'PFC000000006', 'Inisialisasi', 'a:4:{i:0;s:18:"Pc = 2σ cosθ / r";i:1;s:17:"Pc = σ r / cosθ";i:2;s:13:"Pc = Δρ g h";i:3;s:11:"Pc = k / μ";}', 'a:4:{i:0;s:18:"Pc = 2σ cosθ / r";i:1;s:17:"Pc = σ r / cosθ";i:2;s:13:"Pc = Δρ g h";i:3;s:11:"Pc = k / μ";}', '', 'Pc = 2σ cosθ / r', 'Pc = 2σ cosθ / r', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000752', 'Proses drainage adalah proses di mana...', 'The drainage process is the process in which...', 'option', 'PFC000000006', 'Inisialisasi', 'a:4:{i:0;s:55:"Fasa non-wetting mendesak fasa wetting keluar dari pori";i:1;s:38:"Fasa wetting mendesak fasa non-wetting";i:2;s:27:"Dua fasa mengalir bersamaan";i:3;s:30:"Tidak ada fluida yang bergerak";}', 'a:4:{i:0;s:66:"The non-wetting phase displaces the wetting phase out of the pores";i:1;s:49:"The wetting phase displaces the non-wetting phase";i:2;s:25:"Both phases flow together";i:3;s:14:"No fluid moves";}', '', 'Fasa non-wetting mendesak fasa wetting keluar dari pori', 'The non-wetting phase displaces the wetting phase out of the pores', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000753', 'Entry pressure adalah tekanan kapiler minimum yang diperlukan untuk...', 'Entry pressure is the minimum capillary pressure required to...', 'option', 'PFC000000006', 'Inisialisasi', 'a:4:{i:0;s:50:"Memasukkan fasa non-wetting ke dalam pori terbesar";i:1;s:39:"Mengeluarkan seluruh fluida dari batuan";i:2;s:20:"Menghancurkan batuan";i:3;s:24:"Mengubah porositas total";}', 'a:4:{i:0;s:49:"Force the non-wetting phase into the largest pore";i:1;s:30:"Remove all fluid from the rock";i:2;s:14:"Crush the rock";i:3;s:21:"Change total porosity";}', '', 'Memasukkan fasa non-wetting ke dalam pori terbesar', 'Force the non-wetting phase into the largest pore', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000754', 'Permeabilitas relatif (kr) didefinisikan sebagai perbandingan antara...', 'Relative permeability (kr) is defined as the ratio between...', 'option', 'PFC000000006', 'Inisialisasi', 'a:4:{i:0;s:47:"Permeabilitas efektif dan permeabilitas absolut";i:1;s:27:"Permeabilitas dan porositas";i:2;s:37:"Tekanan kapiler dan tekanan reservoir";i:3;s:23:"Viskositas dan densitas";}', 'a:4:{i:0;s:48:"Effective permeability and absolute permeability";i:1;s:25:"Permeability and porosity";i:2;s:41:"Capillary pressure and reservoir pressure";i:3;s:21:"Viscosity and density";}', '', 'Permeabilitas efektif dan permeabilitas absolut', 'Effective permeability and absolute permeability', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000755', 'Saturasi air ireduktibel (Swir) adalah saturasi air yang...', 'Irreducible water saturation (Swir) is the water saturation that...', 'option', 'PFC000000006', 'Inisialisasi', 'a:4:{i:0;s:52:"Tidak dapat dikurangi lagi dengan cara mekanis biasa";i:1;s:20:"Selalu bernilai 100%";i:2;s:27:"Sama dengan saturasi minyak";i:3;s:24:"Terjadi pada tekanan nol";}', 'a:4:{i:0;s:54:"Cannot be reduced further by ordinary mechanical means";i:1;s:14:"Is always 100%";i:2;s:21:"Equals oil saturation";i:3;s:23:"Occurs at zero pressure";}', '', 'Tidak dapat dikurangi lagi dengan cara mekanis biasa', 'Cannot be reduced further by ordinary mechanical means', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000756', 'Saturasi minyak sisa (Sor) adalah...', 'Residual oil saturation (Sor) is...', 'option', 'PFC000000006', 'Inisialisasi', 'a:4:{i:0;s:81:"Minyak yang tertinggal dan tidak dapat diproduksi lagi dengan metode konvensional";i:1;s:26:"Minyak yang baru terbentuk";i:2;s:32:"Minyak yang masih mengalir bebas";i:3;s:28:"Saturasi minyak di permukaan";}', 'a:4:{i:0;s:63:"Oil left behind that cannot be produced by conventional methods";i:1;s:16:"Newly formed oil";i:2;s:27:"Oil that still flows freely";i:3;s:29:"Oil saturation at the surface";}', '', 'Minyak yang tertinggal dan tidak dapat diproduksi lagi dengan metode konvensional', 'Oil left behind that cannot be produced by conventional methods', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000757', 'Faktor apa saja yang memengaruhi tekanan kapiler?', 'Which factors affect capillary pressure?', 'multi', 'PFC000000006', 'Inisialisasi', 'a:4:{i:0;s:23:"Tegangan antarmuka (σ)";i:1;s:26:"Sudut kontak (wettability)";i:2;s:15:"Ukuran pori (r)";i:3;s:12:"Warna batuan";}', 'a:4:{i:0;s:24:"Interfacial tension (σ)";i:1;s:27:"Contact angle (wettability)";i:2;s:13:"Pore size (r)";i:3;s:10:"Rock color";}', '', 'a:3:{i:0;s:23:"Tegangan antarmuka (σ)";i:1;s:26:"Sudut kontak (wettability)";i:2;s:15:"Ukuran pori (r)";}', 'a:3:{i:0;s:24:"Interfacial tension (σ)";i:1;s:27:"Contact angle (wettability)";i:2;s:13:"Pore size (r)";}', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000758', 'Urutkan proses dari kondisi batuan jenuh air sampai terbentuk saturasi air ireduktibel.', 'Arrange the process from a water-saturated rock to the formation of irreducible water saturation.', 'drag', 'PFC000000006', 'Inisialisasi', 'a:4:{i:0;s:22:"Batuan 100% terisi air";i:1;s:39:"Fasa non-wetting mulai masuk (drainage)";i:2;s:25:"Tekanan kapiler meningkat";i:3;s:32:"Air terdesak hingga tersisa Swir";}', 'a:4:{i:0;s:22:"Rock 100% water-filled";i:1;s:44:"Non-wetting phase begins to enter (drainage)";i:2;s:28:"Capillary pressure increases";i:3;s:37:"Water is displaced until Swir remains";}', '', 'a:4:{i:0;s:22:"Batuan 100% terisi air";i:1;s:39:"Fasa non-wetting mulai masuk (drainage)";i:2;s:25:"Tekanan kapiler meningkat";i:3;s:32:"Air terdesak hingga tersisa Swir";}', 'a:4:{i:0;s:22:"Rock 100% water-filled";i:1;s:44:"Non-wetting phase begins to enter (drainage)";i:2;s:28:"Capillary pressure increases";i:3;s:37:"Water is displaced until Swir remains";}', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000759', 'Benarkah kurva relative permeability bergantung pada wettability batuan?', 'Is it true that the relative permeability curve depends on rock wettability?', 'yesorno', 'PFC000000006', 'Inisialisasi', 'a:2:{i:0;s:3:"Yes";i:1;s:2:"No";}', 'a:2:{i:0;s:3:"Yes";i:1;s:2:"No";}', '', 'Yes', 'Yes', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000760', 'Diketahui σ = 0,03 N/m, θ = 30°, dan r = 1 µm. Berapa tekanan kapiler pada pori tersebut?', 'Given σ = 0.03 N/m, θ = 30°, and r = 1 µm. What is the capillary pressure in that pore?', 'option', 'PFC000000006', 'Final Advanced', 'a:4:{i:0;s:9:"0,052 bar";i:1;s:8:"0,52 bar";i:2;s:7:"5,2 bar";i:3;s:6:"52 bar";}', 'a:4:{i:0;s:9:"0.052 bar";i:1;s:8:"0.52 bar";i:2;s:7:"5.2 bar";i:3;s:6:"52 bar";}', '', '0,52 bar', '0.52 bar', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000761', 'Konversi tekanan kapiler dari data laboratorium ke kondisi reservoir dilakukan dengan mengalikan rasio...', 'Converting capillary pressure from laboratory data to reservoir conditions is done by multiplying the ratio of...', 'option', 'PFC000000006', 'Final Advanced', 'a:4:{i:0;s:46:"(σ cosθ) reservoir / (σ cosθ) laboratorium";i:1;s:38:"(σ r) reservoir / (σ r) laboratorium";i:2;s:35:"Porositas reservoir / porositas lab";i:3;s:37:"Viskositas reservoir / viskositas lab";}', 'a:4:{i:0;s:44:"(σ cosθ) reservoir / (σ cosθ) laboratory";i:1;s:36:"(σ r) reservoir / (σ r) laboratory";i:2;s:33:"Reservoir porosity / lab porosity";i:3;s:35:"Reservoir viscosity / lab viscosity";}', '', '(σ cosθ) reservoir / (σ cosθ) laboratorium', '(σ cosθ) reservoir / (σ cosθ) laboratory', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000762', 'Fungsi Leverett J digunakan untuk...', 'The Leverett J-function is used to...', 'option', 'PFC000000006', 'Final Advanced', 'a:4:{i:0;s:43:"Menyeragamkan kurva Pc dari berbagai batuan";i:1;s:24:"Menghitung laju produksi";i:2;s:26:"Menentukan kedalaman sumur";i:3;s:25:"Menghitung viskositas gas";}', 'a:4:{i:0;s:40:"Normalize Pc curves from different rocks";i:1;s:25:"Calculate production rate";i:2;s:20:"Determine well depth";i:3;s:23:"Calculate gas viscosity";}', '', 'Menyeragamkan kurva Pc dari berbagai batuan', 'Normalize Pc curves from different rocks', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000763', 'Jika Pc = 50 kPa, selisih densitas fluida 300 kg/m³, dan g = 9,81 m/s², berapa tinggi kolom di atas free water level?', 'If Pc = 50 kPa, fluid density difference = 300 kg/m³, and g = 9.81 m/s², what is the column height above the free water level?', 'option', 'PFC000000006', 'Final Advanced', 'a:4:{i:0;s:5:"1,7 m";i:1;s:4:"17 m";i:2;s:4:"50 m";i:3;s:5:"170 m";}', 'a:4:{i:0;s:5:"1.7 m";i:1;s:4:"17 m";i:2;s:4:"50 m";i:3;s:5:"170 m";}', '', '17 m', '17 m', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000764', 'Ketika saturasi air menurun dari Sw = 1, relative permeability minyak (kro) akan...', 'As water saturation decreases from Sw = 1, the relative permeability to oil (kro) will...', 'option', 'PFC000000006', 'Final Advanced', 'a:4:{i:0;s:38:"Meningkat dari 0 sampai nilai maksimum";i:1;s:16:"Menurun menuju 0";i:2;s:13:"Tetap konstan";i:3;s:15:"Menjadi negatif";}', 'a:4:{i:0;s:34:"Increase from 0 to a maximum value";i:1;s:17:"Decrease toward 0";i:2;s:15:"Remain constant";i:3;s:15:"Become negative";}', '', 'Meningkat dari 0 sampai nilai maksimum', 'Increase from 0 to a maximum value', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000765', 'Hysteresis pada kurva Pc menunjukkan bahwa...', 'Hysteresis in the Pc curve shows that...', 'option', 'PFC000000006', 'Final Advanced', 'a:4:{i:0;s:45:"Kurva drainage dan imbibition tidak berhimpit";i:1;s:26:"Tekanan kapiler selalu nol";i:2;s:19:"Kurva selalu linier";i:3;s:29:"Wettability tidak berpengaruh";}', 'a:4:{i:0;s:50:"The drainage and imbibition curves do not coincide";i:1;s:33:"Capillary pressure is always zero";i:2;s:26:"The curve is always linear";i:3;s:25:"Wettability has no effect";}', '', 'Kurva drainage dan imbibition tidak berhimpit', 'The drainage and imbibition curves do not coincide', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000766', 'Perubahan wettability dari water-wet menjadi oil-wet umumnya menyebabkan...', 'Changing wettability from water-wet to oil-wet generally causes...', 'option', 'PFC000000006', 'Final Advanced', 'a:4:{i:0;s:43:"Kurva krw bergeser ke kanan dan kro menurun";i:1;s:44:"Kurva krw bergeser ke kiri dan kro meningkat";i:2;s:25:"Tidak ada perubahan kurva";i:3;s:16:"Swir menjadi nol";}', 'a:4:{i:0;s:44:"The krw curve shifts right and kro decreases";i:1;s:43:"The krw curve shifts left and kro increases";i:2;s:23:"No change in the curves";i:3;s:17:"Swir becomes zero";}', '', 'Kurva krw bergeser ke kanan dan kro menurun', 'The krw curve shifts right and kro decreases', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000767', 'Bilangan kapiler (capillary number) yang meningkat menunjukkan...', 'An increasing capillary number indicates...', 'option', 'PFC000000006', 'Final Advanced', 'a:4:{i:0;s:63:"Gaya viskos lebih dominan sehingga saturasi minyak sisa menurun";i:1;s:26:"Gaya kapiler lebih dominan";i:2;s:41:"Tidak ada pengaruh terhadap saturasi sisa";i:3;s:19:"Porositas meningkat";}', 'a:4:{i:0;s:69:"Viscous forces are more dominant so residual oil saturation decreases";i:1;s:34:"Capillary forces are more dominant";i:2;s:32:"No effect on residual saturation";i:3;s:18:"Porosity increases";}', '', 'Gaya viskos lebih dominan sehingga saturasi minyak sisa menurun', 'Viscous forces are more dominant so residual oil saturation decreases', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000768', 'Pada kurva relative permeability, titik kro = 0 biasanya terjadi pada...', 'On the relative permeability curve, the point kro = 0 usually occurs at...', 'option', 'PFC000000006', 'Final Advanced', 'a:4:{i:0;s:37:"Saturasi air tinggi mendekati 1 - Sor";i:1;s:24:"Saturasi air ireduktibel";i:2;s:16:"Saturasi air 50%";i:3;s:20:"Saturasi minyak 100%";}', 'a:4:{i:0;s:41:"High water saturation approaching 1 - Sor";i:1;s:28:"Irreducible water saturation";i:2;s:20:"50% water saturation";i:3;s:19:"100% oil saturation";}', '', 'Saturasi air tinggi mendekati 1 - Sor', 'High water saturation approaching 1 - Sor', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000769', 'Mobility ratio (M) yang lebih besar dari 1 menunjukkan...', 'A mobility ratio (M) greater than 1 indicates...', 'option', 'PFC000000006', 'Final Advanced', 'a:4:{i:0;s:76:"Fluida pendesak lebih mobile daripada fluida terdesak (sweep kurang efisien)";i:1;s:20:"Sweep sangat efisien";i:2;s:16:"Tidak ada aliran";i:3;s:33:"Viskositas pendesak sangat tinggi";}', 'a:4:{i:0;s:73:"The displacing fluid is more mobile than the displaced fluid (poor sweep)";i:1;s:20:"Very efficient sweep";i:2;s:14:"No flow occurs";i:3;s:44:"The displacing fluid has very high viscosity";}', '', 'Fluida pendesak lebih mobile daripada fluida terdesak (sweep kurang efisien)', 'The displacing fluid is more mobile than the displaced fluid (poor sweep)', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000770', 'Metode Purcell digunakan untuk...', 'The Purcell method is used to...', 'option', 'PFC000000006', 'Final Advanced', 'a:4:{i:0;s:50:"Menghitung permeabilitas dari data tekanan kapiler";i:1;s:26:"Menghitung kedalaman sumur";i:2;s:28:"Menentukan jenis hidrokarbon";i:3;s:26:"Mengukur viskositas fluida";}', 'a:4:{i:0;s:51:"Calculate permeability from capillary pressure data";i:1;s:20:"Calculate well depth";i:2;s:26:"Determine hydrocarbon type";i:3;s:23:"Measure fluid viscosity";}', '', 'Menghitung permeabilitas dari data tekanan kapiler', 'Calculate permeability from capillary pressure data', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000771', 'Pengukuran relative permeability metode unsteady-state umumnya menggunakan...', 'The unsteady-state relative permeability measurement method generally uses...', 'option', 'PFC000000006', 'Final Advanced', 'a:4:{i:0;s:80:"Displacement fluida dengan laju tertentu sambil mencatat produksi terhadap waktu";i:1;s:30:"Pengukuran statis tanpa aliran";i:2;s:23:"Pengukuran warna fluida";i:3;s:34:"Pengukuran tekanan overburden saja";}', 'a:4:{i:0;s:71:"Fluid displacement at a given rate while recording production over time";i:1;s:31:"Static measurement without flow";i:2;s:23:"Fluid color measurement";i:3;s:36:"Overburden pressure measurement only";}', '', 'Displacement fluida dengan laju tertentu sambil mencatat produksi terhadap waktu', 'Fluid displacement at a given rate while recording production over time', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000772', 'Manakah pernyataan yang benar tentang kurva tekanan kapiler?', 'Which statements about the capillary pressure curve are correct?', 'multi', 'PFC000000006', 'Final Advanced', 'a:4:{i:0;s:38:"Pori kecil membutuhkan Pc lebih tinggi";i:1;s:45:"Entry pressure berkaitan dengan pori terbesar";i:2;s:29:"Kurva dipengaruhi wettability";i:3;s:43:"Pc tidak bergantung pada tegangan antarmuka";}', 'a:4:{i:0;s:29:"Small pores require higher Pc";i:1;s:45:"Entry pressure is related to the largest pore";i:2;s:36:"The curve is affected by wettability";i:3;s:41:"Pc does not depend on interfacial tension";}', '', 'a:3:{i:0;s:38:"Pori kecil membutuhkan Pc lebih tinggi";i:1;s:45:"Entry pressure berkaitan dengan pori terbesar";i:2;s:29:"Kurva dipengaruhi wettability";}', 'a:3:{i:0;s:29:"Small pores require higher Pc";i:1;s:45:"Entry pressure is related to the largest pore";i:2;s:36:"The curve is affected by wettability";}', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000773', 'Manakah yang memengaruhi bentuk kurva relative permeability?', 'Which factors affect the shape of the relative permeability curve?', 'multi', 'PFC000000006', 'Final Advanced', 'a:4:{i:0;s:18:"Wettability batuan";i:1;s:22:"Distribusi ukuran pori";i:2;s:32:"Saturasi awal dan riwayat aliran";i:3;s:12:"Warna fluida";}', 'a:4:{i:0;s:16:"Rock wettability";i:1;s:22:"Pore size distribution";i:2;s:35:"Initial saturation and flow history";i:3;s:11:"Fluid color";}', '', 'a:3:{i:0;s:18:"Wettability batuan";i:1;s:22:"Distribusi ukuran pori";i:2;s:32:"Saturasi awal dan riwayat aliran";}', 'a:3:{i:0;s:16:"Rock wettability";i:1;s:22:"Pore size distribution";i:2;s:35:"Initial saturation and flow history";}', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000774', 'Manakah aplikasi data tekanan kapiler dalam industri?', 'Which are applications of capillary pressure data in the industry?', 'multi', 'PFC000000006', 'Final Advanced', 'a:4:{i:0;s:48:"Menentukan zona transisi dan distribusi saturasi";i:1;s:51:"Menentukan ketinggian kolom hidrokarbon di atas FWL";i:2;s:26:"Mengestimasi permeabilitas";i:3;s:28:"Menentukan harga jual minyak";}', 'a:4:{i:0;s:59:"Determining the transition zone and saturation distribution";i:1;s:47:"Determining hydrocarbon column height above FWL";i:2;s:23:"Estimating permeability";i:3;s:33:"Determining the oil selling price";}', '', 'a:3:{i:0;s:48:"Menentukan zona transisi dan distribusi saturasi";i:1;s:51:"Menentukan ketinggian kolom hidrokarbon di atas FWL";i:2;s:26:"Mengestimasi permeabilitas";}', 'a:3:{i:0;s:59:"Determining the transition zone and saturation distribution";i:1;s:47:"Determining hydrocarbon column height above FWL";i:2;s:23:"Estimating permeability";}', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000775', 'Manakah pernyataan yang benar tentang saturasi sisa?', 'Which statements about residual saturation are correct?', 'multi', 'PFC000000006', 'Final Advanced', 'a:4:{i:0;s:50:"Sor bergantung pada wettability dan sejarah aliran";i:1;s:36:"Swir dapat diperkirakan dari data Pc";i:2;s:38:"Sor dapat diturunkan dengan metode EOR";i:3;s:27:"Swir selalu sama dengan Sor";}', 'a:4:{i:0;s:43:"Sor depends on wettability and flow history";i:1;s:34:"Swir can be estimated from Pc data";i:2;s:33:"Sor can be reduced by EOR methods";i:3;s:27:"Swir is always equal to Sor";}', '', 'a:3:{i:0;s:50:"Sor bergantung pada wettability dan sejarah aliran";i:1;s:36:"Swir dapat diperkirakan dari data Pc";i:2;s:38:"Sor dapat diturunkan dengan metode EOR";}', 'a:3:{i:0;s:43:"Sor depends on wettability and flow history";i:1;s:34:"Swir can be estimated from Pc data";i:2;s:33:"Sor can be reduced by EOR methods";}', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000776', 'Urutkan tahapan pengukuran kurva tekanan kapiler di laboratorium.', 'Arrange the laboratory capillary pressure curve measurement steps.', 'drag', 'PFC000000006', 'Final Advanced', 'a:5:{i:0;s:21:"Persiapan sampel core";i:1;s:37:"Penjenuhan sampel dengan fasa wetting";i:2;s:50:"Pemberian tekanan bertahap dengan fasa non-wetting";i:3;s:39:"Pencatatan saturasi pada setiap tekanan";i:4;s:18:"Pembuatan kurva Pc";}', 'a:5:{i:0;s:23:"Core sample preparation";i:1;s:44:"Saturating the sample with the wetting phase";i:2;s:54:"Applying pressure in stages with the non-wetting phase";i:3;s:37:"Recording saturation at each pressure";i:4;s:21:"Plotting the Pc curve";}', '', 'a:5:{i:0;s:21:"Persiapan sampel core";i:1;s:37:"Penjenuhan sampel dengan fasa wetting";i:2;s:50:"Pemberian tekanan bertahap dengan fasa non-wetting";i:3;s:39:"Pencatatan saturasi pada setiap tekanan";i:4;s:18:"Pembuatan kurva Pc";}', 'a:5:{i:0;s:23:"Core sample preparation";i:1;s:44:"Saturating the sample with the wetting phase";i:2;s:54:"Applying pressure in stages with the non-wetting phase";i:3;s:37:"Recording saturation at each pressure";i:4;s:21:"Plotting the Pc curve";}', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000777', 'Urutkan nilai saturasi air dari yang tertinggi ke terendah sepanjang proses drainage.', 'Arrange water saturation values from highest to lowest during drainage.', 'drag', 'PFC000000006', 'Final Advanced', 'a:4:{i:0;s:16:"100% (jenuh air)";i:1;s:26:"Zona transisi (Sw menurun)";i:2;s:14:"Mendekati Swir";i:3;s:27:"Saturasi air minimum (Swir)";}', 'a:4:{i:0;s:22:"100% (water saturated)";i:1;s:31:"Transition zone (Sw decreasing)";i:2;s:16:"Approaching Swir";i:3;s:31:"Minimum water saturation (Swir)";}', '', 'a:4:{i:0;s:16:"100% (jenuh air)";i:1;s:26:"Zona transisi (Sw menurun)";i:2;s:14:"Mendekati Swir";i:3;s:27:"Saturasi air minimum (Swir)";}', 'a:4:{i:0;s:22:"100% (water saturated)";i:1;s:31:"Transition zone (Sw decreasing)";i:2;s:16:"Approaching Swir";i:3;s:31:"Minimum water saturation (Swir)";}', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000778', 'Benarkah pada batuan oil-wet, minyak cenderung menempati pori kecil?', 'Is it true that in oil-wet rock, oil tends to occupy small pores?', 'yesorno', 'PFC000000006', 'Final Advanced', 'a:2:{i:0;s:3:"Yes";i:1;s:2:"No";}', 'a:2:{i:0;s:3:"Yes";i:1;s:2:"No";}', '', 'Yes', 'Yes', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000779', 'Benarkah tekanan kapiler dapat bernilai negatif pada proses imbibition?', 'Is it true that capillary pressure can be negative during imbibition?', 'yesorno', 'PFC000000006', 'Final Advanced', 'a:2:{i:0;s:3:"Yes";i:1;s:2:"No";}', 'a:2:{i:0;s:3:"Yes";i:1;s:2:"No";}', '', 'No', 'No', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
